initGridObj();

if(contFormNo === undefined) {
    return;
}

const data = {
    CONT_FORM_NO: contFormNo,
    CONT_TYPE : $share.config.data.CONT_TYPE
};

if(async === undefined) {
    async = true;
}

const config = {
    url: window.CONTEXT_NAME + '/SepoaActionController.sux',
    async: async,
    contentType: "json",
    on: {
        callback: (res, config, params) => {
            $share.config.data['ADD_ROWS'] = {};

            const columnList = [];
            const templateItemList = res.result[0];
            const commonItemList = templateItemList['COMMON_ITEMS'];
            const signerItemList = templateItemList['SIGN_ITEMS'];

            // 공통 아이템을 기준으로 서명자 그리드를 추가한다.
            for(const item of commonItemList) {
                const hasAlready = columnList.find(e => e?.['ITEM_CODE'] == item['ITEM_CODE']) !== undefined;
                if(hasAlready === false) {
                    const itemType = item['ITEM_TYPE'];
                    if(['TEXT', 'NUMBER', 'CALENDAR'].includes(itemType.toUpperCase())) {
                        columnList.push(item);
                    }
                }
            }

            /*
            // 서명자 아이템을 기준으로 서명자 그리드를 추가한다.(업무 방식 변경에 따른 코드 비활성화)
            let targetSigner;
            const companySign = $share.config.data['COMPANY_SIGN'];
            if(companySign === undefined || companySign == 'FIRST') {
                targetSigner = signerItemList.at(-1);
            } else if(companySign == 'LAST') {
                targetSigner = signerItemList.at(0);
            }

            if(targetSigner) {
                for(const item of targetSigner['ITEMS']) {
                    const hasAlready = columnList.find(e => e?.['ITEM_CODE'] == item['ITEM_CODE']) !== undefined;
                    if(hasAlready === false) {
                        const itemType = item['ITEM_TYPE'];
                        if(['TEXT', 'NUMBER', 'CALENDAR'].includes(itemType.toUpperCase())) {
                            columnList.push(item);
                        }
                    }
                }
            }
            */

            // sorting asc, call by reference
            columnList.sort((a, b) => Number(a['ITEM_SEQ']) > Number(b['ITEM_SEQ']) ? 1 : -1);

            const gridColTypeMapper = {
                TEXT        : { type : 'edtxt',         order : 'str'},
                NUMBER      : { type : 'edtxt',         order : 'int'},
                CALENDAR    : { type : 'dhxCalendar',   order : 'int'}
            };

            for(const column of columnList) {
                const lastColumnIndex = gridObj2.columnIds.length;
                const code = column['ITEM_CODE'];
                const name = column['ITEM_NAME'];
                const type = column['ITEM_TYPE'];
                const colWidth = ((name.length * 10) + 20 ) < 120 ? 120 : ((name.length * 10) + 20 );

                if(gridObj2.columnIds.includes(code)) {
                    continue;
                }

                gridObj2.insertColumn(
                    lastColumnIndex,
                    name,
                    gridColTypeMapper[type].type,
                    colWidth * window.devicePixelRatio,
                    gridColTypeMapper[type].order,
                    'center'
                );

                // 그리드 컬럼 ID 지정
                gridObj2.setColumnId(lastColumnIndex, code);

                // 그리드 컬럼 ID 리스트 동기화
                gridObj2.grid_col_id = gridObj2.columnIds;

                // 그리드 컬럼 순서 동기화
                gridObj2._c_order = gridObj2._c_order.sort((x, y) => x - y);

                // 그리드 validator 기본 설정
                gridObj2._validators.data[lastColumnIndex] = ''

            }
        }
    }
}

const params = $.extend(true, {
    module: 'sepoa.svc.ct.ECT_205',
    action: 'doGetTemplateItems'
}, data);

sUtils.multipart.send(config, params);


            let gridId = 'ECT_205_E';
