                    COL_WIDTH : '100',
                    COL_MAX_LEN : '10000',
                    COL_VISIBLE : 'true',
                    COL_ALIGN : 'center',
                    COL_FORMAT : ''
                };
                const forceInsertColumns = [
                    {
                        CODE : 'CONT_FROM',
                        CONTENTS : sUtils.cache.text.get('CT_102_C.CONT_FROM'),
                        COL_TYPE : 'dhxCalendar',
                        COL_SORT : 'int',
                        COL_FORMAT : Sepoa.info['DATE_FORMAT']
                    },
                    {
                        CODE : 'CONT_TO',
                        CONTENTS : sUtils.cache.text.get('CT_102_C.CONT_TO'),
                        COL_TYPE : 'dhxCalendar',
                        COL_SORT : 'int',
                        COL_FORMAT : Sepoa.info['DATE_FORMAT']
                    }
                ];
                const colSeqMap = Object.values(gridOptions).filter(e => e['COL_VISIBLE'] == 'true').map(e => e['COL_SEQ']).sort((e) => true);
                let lastIndex = Math.max(...colSeqMap);
                for(const column of forceInsertColumns) {
                    lastIndex = lastIndex + 0.1;
                    const id = column['CODE'];
                    const columnOption = {
                        ...defaultOption,
                        ...column,
                        COL_SEQ : lastIndex
                    }
                    gridOptions[id] = columnOption;
                }
            }

			gridObj2 = $sObject.gridObj2 = new SepoaDhtmlXGridObject(gridObj2Container, 'gridObj2', gridOptions);
