    } else {
        addSigner(defaultSigner);
    }
} else {
    const signItemList = {};
    const signerList = $share.config.data['SIGNER'];
    const docItem = $share.config.data['DOC_ITEM'];
    if(docItem) {
        for(const [key, value] of Object.entries(docItem)) {
            if(key.startsWith('EX_SIGNER_')) {
                const match = key.replace('EX_SIGNER_', '').match(/^(\d+)_(.*)$/);
                if(match) {
                    const seq = match[1];
                    const itemKey = match[2];

                    if(signItemList[seq] === undefined) {
                        signItemList[seq] = {};
                    }

                    signItemList[seq][itemKey] = value;
                }
            }
        }
    }

    for(const [seq, signItem] of Object.entries(signItemList)) {
        const target = signerList.find(e => e['SEQ'] == seq);
        if(target) {
            for(const [key, value] of Object.entries(signItem)) {
                target[key] = value;
            }
        }
    }

    if(signerList.length > 1) {
        const companySign = docItem?.['EX_COMPANY_SIGN'];
        let signerGroup;
        if([undefined, 'FIRST'].includes(companySign)) {
            signerGroup = signerList.splice(-1, 1)
        } else if(['LAST'].includes(companySign)){
            signerGroup = signerList.splice(0, 1)
        }

        if(signerGroup) {
            for(const signer of signerGroup) {
                signer['SEQ'] = String(signerGroup.indexOf(signer) + 1);
            }

            addGroupSigner(signerGroup);
        }
    }
}


