							if (gridObj2.getColType(columnIndex).includes('combo')) {
								const isComboLoaded = gridObj2._ajaxStatusW.combo == 0;
								if (isComboLoaded === false) {
									const eventId = gridObj2.attachEvent('onComboLoaded', () => {
                                        const cells = gridObj2.cells(rowId, columnIndex);
                                        cells.setValue(value);

                                        let textContent = cells.cell.textContent.trim();
                                        if(sUtils.string.isBlank(textContent)) {
                                            let limit = 0;
                                            const intervalId = setInterval(() => {
                                                limit++;
                                                if(limit >= 1000) {
                                                    clearInterval(intervalId);
                                                }

                                                textContent = cells.cell.textContent.trim();
                                                if(sUtils.string.isBlank(textContent)) {
                                                    cells.refreshCell();
                                                } else {
