		const params = { COLUMN_LIST : JSON.stringify(columnData)};
		sepoaExcelProcessor('down', 'sepoa.svc.ct.ECT_205', 'doExcelDownload', null, 'EMPLOYEE_CONTRACT_SIGNER.xlsx', params);


			let target = 'sepoa.svc.ct.ECT_205';
			const alias = Sepoa.request.alias;
            if(alias === 'B') {
            	target = 'sepoa.svc.ct.CT_205';
            }			
			sepoaExcelProcessor('up', target, 'doExcelUpload', doExcelUploadCallback);


if(res.status == 'true') {
	let uploadList = new SepoaFormater(res.result[0]).getArrayMap();
	const signerList = $share.config.data['SIGNER'];
	const checkList = [];
	for(let i in signerList) {
		checkList.push(signerList[i].SIGNER_ID);
	}
	for(let data of uploadList) {
		if(checkList.indexOf(data.SIGNER_ID) != -1) {
			Alert(Sepoa.cache.text.get('ECT_205_E.MESSAGE_CANNOT_ADD_SIGNER')); // 상신자는 추가할 수 없습니다.
			return;
		}

		// 그리드 캘린더(계약기간 벨리데이션)
		let contFrom = data['CONT_FROM'];
		let contTo = data['CONT_TO'];

		if(!sUtils.string.isBlank(contTo) && !sUtils.string.isBlank(contFrom)){

			// date객체변환
			contFrom = sUtils.date.fromString(contFrom);
			contTo = sUtils.date.fromString(contTo);

			if(contTo.getTime() < contFrom.getTime()){
				Alert( '[ ' + data['SIGNER_ID'] + ' / ' + data['SIGNER_NAME'] + ' ] ' + Sepoa.cache.text.get('ECT_205_E.MESSAGE_CALENDER')); 
				// [ SIGNER_ID / SIGNER_NAME ] 계약시작일 또는 계약종료일이 올바르지 않습니다.
				return;						
			}
		}
	}
	gridObj2.clearAll();
	addGroupSigner(uploadList);
}else {
	Alert(res.message);
}


let myCompany;
const service = 'sepoa.svc.ct.ECT_205_E_POPUP';
const companySO = doServiceAjax(service, 'CONNECTION', 'doQueryCompany', {}, null, false);
if(companySO.status == '1') {
    const companyList = new SepoaFormater(companySO.result[0]).getArrayMap();
    if(companyList.length == 0) {
        // 현재 사용자에 대한 계약자 정보 조회에 실패했습니다.<br>관리자에게 문의해 계약자 등록을 진행해주세요.
        return;
    }

    myCompany = companyList.find(e => e['SIGNER_COMPANY_CODE'] == Sepoa.info['COMPANY_CODE']);
    if(myCompany === undefined) {
        return;
    }
}

let targetManager;
const managerParams = {
    ...myCompany,
    F_KEYWORD : Sepoa.info['ID']
};
const managerSO = doServiceAjax(service, 'CONNECTION', 'doQuerySigner', managerParams, null, false);
if (managerSO.status == '1') {
    const managerList = new SepoaFormater(managerSO.result[0]).getArrayMap();
    if(managerList.length <= 0) {
        return;
    }

    targetManager = managerList.find(e => e['SIGNER_ID'] == Sepoa.info['ID']);
    if(targetManager === undefined) {
        return;
    }
}

const alias = Sepoa.request.alias;
const category = alias == 'B' ? 'C' : 'COMPANY';

return {
    ...myCompany,
    ...targetManager,
    SEQ : '1',
    CATEGORY : category
};
